xql_query:
// ============================================================
// Rule: WIN_Suspicious Kernel Driver Load from Risky Path
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_Suspicious Kernel Driver Load from Risky Path.
// Severity: SEV_040_HIGH
// Category: PRIVILEGE_ESCALATION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0004 - Privilege Escalation
// Technique: T1068 - Exploitation for Privilege Escalation

config case_sensitive = false

| dataset = xdr_data

| filter agent_os_type = ENUM.AGENT_OS_WINDOWS
| filter event_type = ENUM.LOAD_IMAGE

| alter module_path_lc = lowercase(action_module_path)

| filter module_path_lc ~= ".*\\\\[^\\\\]+\\.sys$"

// High-risk load locations; standard driver stores are not included
| filter module_path_lc ~= "^(c:\\\\users\\\\|c:\\\\windows\\\\temp\\\\|c:\\\\temp\\\\|c:\\\\programdata\\\\[^\\\\]+\\\\temp\\\\|\\\\\\\\)"

| fields
    _time,
    agent_hostname,
    agent_id,
    agent_ip_addresses,
    actor_effective_username,
    actor_process_image_name,
    actor_process_image_path,
    actor_process_command_line,
    action_module_path,
    action_module_sha256,
    action_module_signature_status,
    action_module_signature_vendor,
    action_module_wf_verdict,
    event_type,
    event_sub_type
